mapper.update:
update lf_post
set lifecycle_status = 'PENDING_REVIEW',
    review_status = 'PENDING',
    version = version + 1,
    update_time = sysdate()
where post_id = #{postId}
  and publisher_id = #{publisherId}
  and version = #{version}
  and lifecycle_status in ('DRAFT', 'REJECTED')
  and del_flag = '0'

update lf_post
set lifecycle_status = 'WITHDRAWN',
    version = version + 1,
    update_time = sysdate()
where post_id = #{postId}
  and publisher_id = #{publisherId}
  and version = #{version}
  and lifecycle_status in ('DRAFT', 'PENDING_REVIEW', 'PUBLISHED')
  and del_flag = '0'

mapper.insert:
insert into lf_post_review (
    post_id, reviewer_id, action, before_status, after_status, reason, create_time
) values (
    #{postId}, #{reviewerId}, #{action}, #{beforeStatus}, #{afterStatus}, #{reason}, sysdate()
)

insert into lf_post_event (
    post_id, event_type, from_status, to_status, operator_id, source, reason, create_time
) values (
    #{postId}, #{eventType}, #{fromStatus}, #{toStatus}, #{operatorId}, #{source}, #{reason}, sysdate()
)

