update lf_post_image
set access_url = #{accessUrl}
where image_id = #{imageId}
  and post_id = #{postId}
  and del_flag = '0'

update lf_post_image
set review_status = #{reviewStatus}
where post_id = #{postId}
  and del_flag = '0'
